function initMenu(){
 const groups={"Cardiovascular":{"Presentations":["Chest pain","Palpitations","Blackouts and faints"],"Conditions":["Acute coronary syndromes","Heart failure","Atrial fibrillation"]},"Respiratory":{"Presentations":["Breathlessness","Cough","Haemoptysis"],"Conditions":["Asthma","Chronic obstructive pulmonary disease","Pneumonia"]},"Neurological":{"Presentations":["Headache","Limb weakness","Fits/seizures"],"Conditions":["Stroke","Epilepsy","Meningitis"]},"Gastrointestinal":{"Presentations":["Abdominal pain (acute and chronic)","Jaundice","Bleeding per rectum"],"Conditions":["Acute pancreatitis","Inflammatory bowel disease","Appendicitis"]}};
 const catalogue=[]; let selected=null;
 const root=document.getElementById('topics');
 function choose(topic){selected=topic;document.getElementById('selection').textContent='Selected: '+topic;document.getElementById('start').disabled=false;}
 function random(topics){choose(topics[Math.floor(Math.random()*topics.length)]);}
 for(const [group,kinds] of Object.entries(groups)){
  const section=document.createElement('details');const summary=document.createElement('summary');summary.textContent=group;section.append(summary);
  const pool=[];
  for(const [kind,topics] of Object.entries(kinds)){
   const sub=document.createElement('details');const heading=document.createElement('summary');heading.textContent=kind;sub.append(heading);
   for(const topic of topics){if(!catalogue.includes(topic))catalogue.push(topic);if(!pool.includes(topic))pool.push(topic);const button=document.createElement('button');button.textContent=topic;button.onclick=()=>choose(topic);sub.append(button);}
   section.append(sub);
  }
  const pick=document.createElement('button');pick.textContent='Random in '+group;pick.onclick=()=>random(pool);section.append(pick);root.append(section);
 }
 const count=document.getElementById('count');
 document.getElementById('less').onclick=()=>count.value=String(Math.max(1,(Number(count.value)||12)-1));
 document.getElementById('more').onclick=()=>count.value=String((Number(count.value)||12)+1);
 document.getElementById('random-all').onclick=()=>random(catalogue);
 document.getElementById('start').onclick=async()=>{
  const n=Number(count.value);const status=document.getElementById('status');
  if(!selected||!Number.isSafeInteger(n)||n<1){status.textContent='Choose a topic and a positive whole-number question count.';return;}
  const button=document.getElementById('start');button.disabled=true;
  try{await Websandbox.connection.remote.sendPrompt({text:'Begin a progressive medical case on '+selected+'. Ask '+n+' questions, one at a time, at experienced-doctor level.'});status.textContent='Request submitted.';}
  catch(e){status.textContent='Request was not sent. You can try again.';}
  finally{button.disabled=false;}
 };
}
